    /// CMIS 4.0 per-byte classification, generated from access and read-effect metadata.
    /// Indices are page-relative; missing/unknown assertions never qualify as None.
    /// Unknown change-source metadata is conservatively dynamic (not cache-static).
    pub fn read_classifications() -> [openxcvr_core::types::management::ByteClassification; 128] {
        use openxcvr_core::types::management::{ByteClassification, ChangeSource, ReadEffect};
        std::array::from_fn(|index| match index {
            0..=3 => {
                ByteClassification::from_masks(0x00, 0xff, 0x00, 0x00, &[], ChangeSource::Dynamic)
            }
            4 => ByteClassification::from_masks(0x00, 0x00, 0xff, 0x00, &[], ChangeSource::Static),
            5 => ByteClassification::from_masks(0x00, 0x00, 0xff, 0x00, &[], ChangeSource::Static),
            6..=24 => ByteClassification::from_masks(
                0xff,
                0x00,
                0x00,
                0x00,
                &[ReadEffect::ClearOnRead],
                ChangeSource::Dynamic,
            ),
            25 => ByteClassification::from_masks(0x00, 0x00, 0xff, 0x00, &[], ChangeSource::Static),
            26..=106 => {
                ByteClassification::from_masks(0x00, 0xff, 0x00, 0x00, &[], ChangeSource::Dynamic)
            }
            107..=111 => {
                ByteClassification::from_masks(0x00, 0x00, 0xff, 0x00, &[], ChangeSource::Static)
            }
            112..=127 => {
                ByteClassification::from_masks(0x00, 0xff, 0x00, 0x00, &[], ChangeSource::Static)
            }
            _ => unreachable!("array index"),
        })
    }
